class TestRedirectDefault:
    """Test that redirect defaults to 303 instead of 302."""

    def test_redirect_default_no_app(self):
        """Call redirect without specifying a code, no app context."""
        response = flask.redirect("https://example.com")
        assert response.status_code == 303

    def test_redirect_default_with_app(self, app):
        """Call redirect without specifying a code, with app context."""
        with app.app_context():
